Algorithm DibujarTablero
  Dimension tablero[3, 3] As Integer;
  tablero[0, 0] <- 1;
  tablero[0, 1] <- 2;
  tablero[0, 2] <- 1;
  tablero[1, 0] <- 2;
  tablero[1, 1] <- 1;
  tablero[1, 2] <- 2;
  tablero[2, 0] <- 2;
  tablero[2, 1] <- 1;
  tablero[2, 2] <- 1;
  For f <- 0 To 2 Do
    Define linea As String <- "";
    For c <- 0 To 2 Do
      Switch tablero[f, c] Do
        1:
          linea <- linea + "X";
        2:
          linea <- linea + "O";
        Otherwise:
          linea <- linea + ".";
      EndSwitch
    EndFor
    Write linea;
  EndFor
EndAlgorithm

Algorithm TresEnRaya
  Dimension t[3, 3] As Integer;
  For f <- 0 To 2 Do
    For c <- 0 To 2 Do
      Read t[f, c];
    EndFor
  EndFor
  Define ganador As Integer <- 0;
  For i <- 0 To 2 Do
    If t[i, 0] <> 0 And t[i, 0] = t[i, 1] And t[i, 1] = t[i, 2] Then
      ganador <- t[i, 0];
    EndIf
    If t[0, i] <> 0 And t[0, i] = t[1, i] And t[1, i] = t[2, i] Then
      ganador <- t[0, i];
    EndIf
  EndFor
  If t[1, 1] <> 0 And t[0, 0] = t[1, 1] And t[1, 1] = t[2, 2] Then
    ganador <- t[1, 1];
  EndIf
  If t[1, 1] <> 0 And t[0, 2] = t[1, 1] And t[1, 1] = t[2, 0] Then
    ganador <- t[1, 1];
  EndIf
  Switch ganador Do
    1:
      Write "Gana X";
    2:
      Write "Gana O";
    Otherwise:
      Write "Nadie";
  EndSwitch
EndAlgorithm
